import React, { useEffect, useState } from 'react';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { scykRoutes } from '../../config/scykRoutes';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import {
  fetchDailyIncidentReports,
  fetchDailyIncidentReportStats,
  deleteDailyIncidentReport,
  setFilters,
  setPage,
  defaultDailyReportYearFilters,
} from '../../store/slices/dailyIncidentReportsSlice';
import { addToast } from '../../store/slices/uiSlice';
import { useResponsive } from '../../hooks/useResponsive';
import { useMinLoadingTime } from '../../hooks/useMinLoadingTime';
import { useExportExcel } from '../../hooks/useExportExcel';
import { DailyIncidentReportFiltersBar } from './components/DailyIncidentReportFiltersBar';
import { DailyIncidentStatsCards } from './components/DailyIncidentStatsCards';
import { dailyIncidentReportEndpoint } from '../../services/dailyIncidentReports/endpoint';
import type { DailyIncidentReport, DailyIncidentReportFilters } from '../../models/DailyIncidentReport';
import styles from './DailyIncidentReportsListPage.module.css';

import { Button, TableCard, Pagination, ExportConfirmModal, useAlert } from '@linm-soft-org/linm-web-common-components';
import { ErpFilterCardHeader } from '../../components/layout/ErpFilterCardHeader';
const DailyIncidentReportsListPage: React.FC = () => {
  const appNavigate = useAppNavigate();
  const dispatch  = useAppDispatch();
  const { isMobile } = useResponsive();
  const alert = useAlert();

  const { items, loading, filters, pagination, stats, statsLoading } = useAppSelector(
    (s) => s.dailyIncidentReports,
  );
  const showLoading = useMinLoadingTime(loading);

  const [localFilters, setLocalFilters] = useState<DailyIncidentReportFilters>(filters);
  const [showExportModal, setShowExportModal] = useState(false);

  const exportColumns = [
    { key: 'no',             label: 'STT',             width: 6  },
    { key: 'reportedDate',   label: 'Ngày báo cáo',   width: 16 },
    { key: 'departmentName', label: 'Khoa/Phòng',      width: 28 },
    { key: 'idCode',         label: 'Mã GS',           width: 14 },
    { key: 'hasIncident',    label: 'Có sự cố',       width: 12 },
    { key: 'incidentCount',  label: 'Số lượng sự cố', width: 20 },
    { key: 'createdByName',  label: 'Người tạo',      width: 24 },
    { key: 'createdAt',      label: 'Ngày tạo',       width: 20 },
  ];

  const exportRows = items.map((item, idx) => ({
    no:             (pagination.page - 1) * pagination.pageSize + idx + 1,
    reportedDate:   item.reportedDate ?? '',
    departmentName: item.departmentName,
    idCode:         item.idCode,
    hasIncident:    item.hasIncident ? 'Có' : 'Không',
    incidentCount:  item.hasIncident ? item.incidentCount : '',
    createdByName:  item.createdByName ?? '',
    createdAt:      formatCreatedAt(item.createdAt),
  }));

  const { exportExcel } = useExportExcel();

  const handleExportCurrent = () => {
    exportExcel({ fileName: 'BaoCaoHangNgay', sheetName: 'Báo Cáo Hàng Ngày', columns: exportColumns, rows: exportRows });
    setShowExportModal(false);
  };

  const handleExportAll = async () => {
    const blob = await dailyIncidentReportEndpoint.exportAll(filters);
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href     = url;
    a.download = `BaoCaoHangNgay_${new Date().toISOString().slice(0, 10)}.xlsx`;
    a.click();
    URL.revokeObjectURL(url);
    setShowExportModal(false);
  };

  useEffect(() => {
    const timer = setTimeout(() => { dispatch(fetchDailyIncidentReports()); }, 0);
    return () => clearTimeout(timer);
  }, [dispatch, filters, pagination.page]);

  // Reload stats whenever base filters (date/dept) change — not hasIncident
  useEffect(() => {
    const timer = setTimeout(() => { dispatch(fetchDailyIncidentReportStats()); }, 0);
    return () => clearTimeout(timer);
  }, [dispatch, filters.fromDate, filters.toDate, filters.departmentId]);

  const handleFilterChange = (next: DailyIncidentReportFilters) => {
    setLocalFilters(next);
    dispatch(setFilters(next));
  };

  const handleClearFilters = () => {
    const next = defaultDailyReportYearFilters();
    setLocalFilters(next);
    dispatch(setFilters(next));
  };

  /** Derive active stats filter from redux filters */
  const activeStatsFilter: 'all' | 'with' | 'without' = (() => {
    if (filters.hasIncident === true)  return 'with';
    if (filters.hasIncident === false) return 'without';
    return 'all';
  })();

  const handleStatsFilter = (key: 'all' | 'with' | 'without') => {
    const next: DailyIncidentReportFilters = {
      ...filters,
      hasIncident: key === 'all' ? undefined : key === 'with',
    };
    setLocalFilters(next);
    dispatch(setFilters(next));
  };

  const totalPages = pagination.totalCount > 0
    ? Math.ceil(pagination.totalCount / pagination.pageSize)
    : 1;

  const handleDelete = (item: DailyIncidentReport) => {
    alert.confirm(
      `Xóa báo cáo ${item.idCode}? Ngày báo cáo khác ngày tạo.`,
      async () => {
        const result = await dispatch(deleteDailyIncidentReport(item.id));
        if (deleteDailyIncidentReport.fulfilled.match(result)) {
          dispatch(addToast({ type: 'success', message: 'Đã xóa báo cáo.' }));
          dispatch(fetchDailyIncidentReports());
          dispatch(fetchDailyIncidentReportStats());
        } else {
          dispatch(addToast({ type: 'error', message: 'Không xóa được báo cáo. Vui lòng thử lại.' }));
        }
      },
    );
  };

  const handleRowClick = (item: DailyIncidentReport) => {
    const params = new URLSearchParams();
    if (item.departmentId) params.set('reportingDepartmentId', item.departmentId);
    if (item.reportedDate) {
      params.set('dateFrom', item.reportedDate);
      params.set('dateTo',   item.reportedDate);
    }
    appNavigate(`${scykRoutes.incidents.list}?${params.toString()}`);
  };

  return (
    <div className={styles.page} data-catalog-list-page data-lin-list-layout="erp-filter-bar">
      {/* Page header: title left, action buttons right — single compact row */}
      <div className={styles.pageHeader}>
        <div className={styles.titleGroup}>
          <i className="fas fa-calendar-check" />
          <h1 className={styles.title}>Báo Cáo Hàng Ngày</h1>
        </div>
        <div className={styles.headerActions}>
          <Button variant="secondary" onClick={() => setShowExportModal(true)}>
            <i className="fas fa-file-excel" />{!isMobile && ' Xuất Excel'}
          </Button>
          <Button variant="primary" onClick={() => appNavigate(scykRoutes.dailyReports.new)}>
            <i className="fas fa-plus" />{!isMobile && ' Báo Cáo Hôm Nay'}
          </Button>
        </div>
      </div>

      {/* Stats cards — API-driven, clickable to filter */}
      <DailyIncidentStatsCards
        stats={stats}
        loading={statsLoading}
        activeFilter={activeStatsFilter}
        onFilter={handleStatsFilter}
      />

      {/* Table card */}
      <TableCard
        header={
          <ErpFilterCardHeader title="Danh sách báo cáo" testIdPrefix="daily-incident-report-list">
            <DailyIncidentReportFiltersBar
              filters={localFilters}
              onChange={handleFilterChange}
              onClear={handleClearFilters}
              loading={showLoading}
            />
          </ErpFilterCardHeader>
        }
        footer={
          <Pagination
            currentPage={pagination.page}
            totalPages={totalPages}
            totalCount={pagination.totalCount}
            pageSize={pagination.pageSize}
            onPageChange={(p) => dispatch(setPage(p))}
          />
        }
      >
        {showLoading ? (
          <div className={styles.loadingRow}>
            <i className="fas fa-spinner fa-spin" /> Đang tải...
          </div>
        ) : items.length === 0 ? (
          <div className={styles.emptyRow}>Chưa có báo cáo nào.</div>
        ) : isMobile ? (
          <div className={styles.mobileList}>
            {items.map((item, idx) => (
              <MobileCard key={item.id} item={item} index={idx} page={pagination.page} pageSize={pagination.pageSize} onNavigate={handleRowClick} onDelete={handleDelete} />
            ))}
          </div>
        ) : (
          <table className={styles.table}>
            <thead>
              <tr>
                <th style={{ width: 48 }}>STT.</th>
                <th>Ngày báo cáo ↓</th>
                <th>Ngày tạo</th>
                <th></th>
                <th>Khoa, phòng</th>
                <th>Mã GS</th>
                <th>Trong ngày có Sự cố...</th>
                <th>Số lượng</th>
                <th>Xóa</th>
              </tr>
            </thead>
            <tbody>
              {items.map((item, idx) => (
                <TableRow key={item.id} item={item} index={idx} page={pagination.page} pageSize={pagination.pageSize} onNavigate={handleRowClick} onDelete={handleDelete} />
              ))}
            </tbody>
          </table>
        )}
      </TableCard>

      <ExportConfirmModal
        isOpen={showExportModal}
        onClose={() => setShowExportModal(false)}
        currentPageCount={items.length}
        totalCount={pagination.totalCount}
        onExportCurrent={handleExportCurrent}
        onExportAll={handleExportAll}
      />
    </div>
  );
};

// ─── Sub-components ─────────────────────────────────────────────────────────

const TableRow: React.FC<{ item: DailyIncidentReport; index: number; page: number; pageSize: number; onNavigate: (item: DailyIncidentReport) => void; onDelete: (item: DailyIncidentReport) => void }> = ({ item, index, page, pageSize, onNavigate, onDelete }) => {
  const date = item.reportedDate
    ? new Date(item.reportedDate + 'T00:00:00').toLocaleDateString('vi-VN')
    : '';
  const createdDate = formatCreatedAt(item.createdAt);
  const canDelete = reportedDateDiffersFromCreated(item);
  const no = (page - 1) * pageSize + index + 1;

  return (
    <tr onClick={() => onNavigate(item)} style={{ cursor: 'pointer' }}>
      <td style={{ color: 'var(--color-text-muted, #adb5bd)', textAlign: 'center' }}>{no}</td>
      <td>{date}</td>
      <td>{createdDate}</td>
      <td><i className="fas fa-envelope" style={{ color: '#6c757d' }} /></td>
      <td>{item.departmentName}</td>
      <td>{item.idCode}</td>
      <td>
        <span className={item.hasIncident ? styles.badgeYes : styles.badgeNo}>
          {item.hasIncident ? 'Có' : 'Không'}
        </span>
      </td>
      <td>{item.hasIncident ? item.incidentCount : ''}</td>
      <td>
        {canDelete && (
          <button type="button" className={styles.deleteBtn} onClick={(e) => { e.stopPropagation(); onDelete(item); }}>
            Xóa
          </button>
        )}
      </td>
    </tr>
  );
};

const MobileCard: React.FC<{ item: DailyIncidentReport; index: number; page: number; pageSize: number; onNavigate: (item: DailyIncidentReport) => void; onDelete: (item: DailyIncidentReport) => void }> = ({ item, index, page, pageSize, onNavigate, onDelete }) => {
  const date = item.reportedDate
    ? new Date(item.reportedDate + 'T00:00:00').toLocaleDateString('vi-VN')
    : '';
  const createdDate = formatCreatedAt(item.createdAt);
  const canDelete = reportedDateDiffersFromCreated(item);
  const no = (page - 1) * pageSize + index + 1;

  return (
    <div className={styles.mobileCard} onClick={() => onNavigate(item)} style={{ cursor: 'pointer' }}>
      <div className={`${styles.mobileRow} ${styles.mobileRowHeader}`}>
        <span className={styles.mobileStt}>#{no}</span>
        <span className={item.hasIncident ? styles.badgeYes : styles.badgeNo}>
          {item.hasIncident ? 'Có sự cố' : 'Không có sự cố'}
        </span>
      </div>
      <div className={styles.mobileRow}>
        <span className={styles.mobileLabel}>Ngày báo cáo</span>
        <span>{date}</span>
      </div>
      <div className={styles.mobileRow}>
        <span className={styles.mobileLabel}>Ngày tạo</span>
        <span>{createdDate}</span>
      </div>
      <div className={styles.mobileRow}>
        <span className={styles.mobileLabel}>Khoa, phòng</span>
        <span>{item.departmentName}</span>
      </div>
      <div className={styles.mobileRow}>
        <span className={styles.mobileLabel}>Mã GS</span>
        <span>{item.idCode}</span>
      </div>
      {item.hasIncident && (
        <div className={styles.mobileRow}>
          <span className={styles.mobileLabel}>Số lượng sự cố</span>
          <span>{item.incidentCount}</span>
        </div>
      )}
      {canDelete && (
        <button type="button" className={styles.deleteBtn} onClick={(e) => { e.stopPropagation(); onDelete(item); }}>
          Xóa
        </button>
      )}
    </div>
  );
};

function formatCreatedAt(iso: string | null | undefined): string {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return d.toLocaleString('vi-VN', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function reportedDateDiffersFromCreated(item: DailyIncidentReport): boolean {
  if (!item.reportedDate || !item.createdAt) return false;
  const created = new Date(item.createdAt);
  if (Number.isNaN(created.getTime())) return false;
  const local = `${created.getFullYear()}-${String(created.getMonth() + 1).padStart(2, '0')}-${String(created.getDate()).padStart(2, '0')}`;
  return item.reportedDate.slice(0, 10) !== local;
}

export default DailyIncidentReportsListPage;
